/**
 * The ONLY way TypeScript clients (web, journeys, scripts) call the API (ADR-002).
 * `schema.d.ts` is generated by `make client-gen` — never edit it by hand.
 */
import createClient, { type ClientOptions } from 'openapi-fetch';
import type { components, paths } from './schema';

export type { components, paths };
export type Schemas = components['schemas'];
export type ApiClient = ReturnType<typeof createApiClient>;

export function createApiClient(baseUrl: string, options: Omit<ClientOptions, 'baseUrl'> = {}) {
  return createClient<paths>({ ...options, baseUrl });
}

/** Fresh Idempotency-Key for a write; reuse the same key when retrying the same intent. */
export function newIdempotencyKey(): string {
  return crypto.randomUUID();
}
